import { useState } from "react";

type Hit = { id: string; title: string; url: string };

export function Search() {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<Hit[]>([]);

  async function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    const value = e.target.value;
    setQuery(value);
    if (!value.trim()) {
      setResults([]);
      return;
    }
    const res = await fetch(`/api/search?q=${encodeURIComponent(value)}`);
    const data: Hit[] = await res.json();
    setResults(data);
  }

  return (
    <div className="search">
      <input value={query} onChange={handleChange} placeholder="Search docs" />
      <ul>
        {results.map((hit) => (
          <li key={hit.id}>
            <a href={hit.url}>{hit.title}</a>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useRef, useState } from "react";
import { searchProducts, type Product } from "@/lib/api";

export function useDebouncedSearch(delay = 300) {
  const [results, setResults] = useState<Product[]>([]);
  const [loading, setLoading] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout>>();

  function search(term: string) {
    clearTimeout(timer.current);
    timer.current = setTimeout(async () => {
      setLoading(true);
      try {
        const items = await searchProducts(term);
        setResults(items);
      } finally {
        setLoading(false);
      }
    }, delay);
  }

  return { results, loading, search };
}

