import { EventEmitter } from "node:events";

export type ServiceStatus = { name: string; healthy: boolean; latencyMs: number };

export class StatusBoard extends EventEmitter {
  private statuses: ServiceStatus[] = [];
  private timer?: NodeJS.Timeout;

  constructor(private readonly endpoint: string) {
    super();
  }

  start(intervalMs = 3000) {
    this.timer = setInterval(async () => {
      const res = await fetch(this.endpoint);
      this.statuses = (await res.json()) as ServiceStatus[];
      this.emit("update", this.statuses);
    }, intervalMs);
  }

  stop() {
    if (this.timer) clearInterval(this.timer);
  }

  get current() {
    return this.statuses;
  }
}

