import { useEffect, useState } from "react";

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

export function DeployLog({ deployId }: { deployId: string }) {
  const [lines, setLines] = useState<string[]>([]);

  useEffect(() => {
    let cancelled = false;

    async function poll() {
      while (!cancelled) {
        const res = await fetch(`/api/deploys/${deployId}/log`);
        const body: { lines: string[]; finished: boolean } = await res.json();
        if (cancelled) return;
        setLines(body.lines);
        if (body.finished) return;
        await sleep(2000);
      }
    }

    poll();
    return () => {
      cancelled = true;
    };
  }, [deployId]);

  return <pre>{lines.join("\n")}</pre>;
}

