type Props = { amountCents: number; currency?: string; strikethrough?: boolean };

const formatters = new Map<string, Intl.NumberFormat>();

function formatter(currency: string) {
  let f = formatters.get(currency);
  if (!f) {
    f = new Intl.NumberFormat("en-US", { style: "currency", currency });
    formatters.set(currency, f);
  }
  return f;
}

export function PriceTag({ amountCents, currency = "USD", strikethrough = false }: Props) {
  const text = formatter(currency).format(amountCents / 100);
  return strikethrough ? <s>{text}</s> : <span>{text}</span>;
}

